function ActivityFashionPreheating:StartCountDownCo()
    if isNotNull(self.countDownCo) then
        cs_coroutine.stop(self.countDownCo)
        self.countDownCo = nil
    end
    local time = os.time()
    ---@type PlayerDojo
    local playerDojo = PlayerComponent.playerDojo
    local serverTime = playerDojo:GetServerTime()
    local distanceTime = self.prizeCountDown - serverTime 
    local currentTime = os.time() - time
    if currentTime < distanceTime then
        self.FontStyleButton:ResetFontStyle( "B17", localize("_time_后开启" ,{_time_ = CfUtils.GetTimeHMS(distanceTime - currentTime )}))
    else 
        self.FontStyleButton:ResetFontStyle( "B1", localize("抽取"))  
    end
    self.countDownCo = cs_coroutine.start(function ()
        while currentTime < distanceTime do 
            cs_coroutine.yield_return( CS.Engine.Lib.Yielders.GetWaitForSeconds(1))
            currentTime = os.time() - time
            CfUtils.FillText(self.FontStyleButton.CachedText.gameObject  ,localize("_time_后开启" , {_time_ = CfUtils.GetTimeHMS(distanceTime - currentTime )}) ) 
            -- self.FontStyleButton:ResetFontStyle( "B17", localize("_time_后开启" ,{_time_ = CfUtils.GetTimeHMS(distanceTime - currentTime )}))
        end    
        self.FontStyleButton:ResetFontStyle( "B1", localize("抽取"))  
    end)
end
