function ActivityFashionPreheating:Refresh(activityDojo)
    self.activityDt   = activityDojo
    if isNull(self.animMapList) then
        return
    end
    GameUtils.Request(Interfaces.Activity2SkinWarmUp, {activityUuid = self:GetActivityId()},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = response.data
                    self.taskData     = checkTable(data.tasks)
                    self.taskConf     = checkTable(data.activityTaskConf)
                    self.consumeData = checkTable(data.consume)
                    self.myPrize = checkTable(data.myPrize)
                    self.bigPrizeRecord = checkTable(data.bigPrizeRecord)
                    self.ruleId = checkInt(data.ruleId)
                    self.subPrefab = checkString(data.subPrefab)
                    ---@type PlayerDojo
                    local playerDojo = PlayerComponent.playerDojo
                    local serverTime = playerDojo:GetServerTime()
                    self.prizeCountDown = serverTime + data.prizeCountDown
                    if not KTool.IsActive(self.SafeAreaGroup) then
                        KTool.SetActive(self.SafeAreaGroup.gameObject , true )
                    end
                    -- init data
                    self:InitRewardsDt()
                    -- init event
                    self:InitBindEvent()
                    -- update view
                    self:InitView()
                    self:StartCountDownCo()
                    -- update topBar
                    -- self:RefreshCurrencyBarInfo()
                end
            end
    )
end

