function ActivityFashionPreheating:InitRewardsDt()
    self.canTaskMap = {}
    for _, taskDt in pairs(self:GetTaskDt()) do
        if taskDt.status == Constants.GetStatus.Can then
            self.canTaskMap[checkInt(taskDt.taskId)] = true
        end
    end

    table.sort(self:GetTaskDt(), function(a, b)
        local aStatus = checkInt(a.status)
        local bStatus = checkInt(b.status)
        if aStatus ~= bStatus then
            if aStatus == Constants.GetStatus.Can or bStatus == Constants.GetStatus.Can then
                return aStatus == Constants.GetStatus.Can
            else
                return aStatus < bStatus
            end
        else
            return checkInt(a.id) < checkInt(b.id)
        end
    end)

    ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), next(self:GetCanIdMap()) == nil and -1 or 0)
end

function ActivityFashionPreheating:InitBindEvent()
    SetButtonAction(self.FontStyleButton, function ()
        local time = os.time()
        ---@type PlayerDojo
        local playerDojo = PlayerComponent.playerDojo
        local serverTime = playerDojo:GetServerTime()
        local distanceTime = self.prizeCountDown - serverTime 
        local currentTime = os.time() - time
        if currentTime < distanceTime then
            GameUtils.Toast(localize("活动暂未开启"))
            return
        end
        local  num =  GoodsUtils.GetThingNo(self.consumeData[1].goodsId)  
        local oneNum = self.consumeData[1].num 
        if checkInt(oneNum) > checkInt(num) then
            GameUtils.Toast(localize("道具不足"))
            return
        end
        self:FlashSkinWarmUpPrize()
    end)
    
    local bigRewards = ActivityFashionPreheatingUtils.GetBigReardsVo(self:GetActivityDt().activityContentId)
    local roleNode = self.ImgRole:Find("roleNode")
    if isNull(roleNode) then
        self.loadCo = cs_coroutine.start(
            function ()
                local path = string.format("Prefabs/Activity/%s.prefab", self.subPrefab )
                local roleNode = GameUtils.LoadBundleAsync(path ,self.ImgRole.gameObject ,  false) 
                roleNode.name = "roleNode"   
                --self.BtnRoleNameNode1 , self.BtnRoleNameNode2
                local BtnRoleNameNodes = {}
                for i  = 1 , #bigRewards do
                    local BtnRoleNameNode = roleNode.transform:Find("BtnRoleNameNode" .. i)
                    if isNotNull(BtnRoleNameNode) then
                        BtnRoleNameNodes[#BtnRoleNameNodes+1] = BtnRoleNameNode
                    end
                end
                for k, v in ipairs(bigRewards) do
                    self:RefreshBtnRoleNameNode(v.rewardId ,BtnRoleNameNodes[k])
                end
            end
        )
    end
    local isShow = false 
    if isNotNull(self.myPrize)  and table.count(self.myPrize) > 0  then
        isShow = true
        self:RefreshGoodNode()
    end
    KTool.SetActive(self.RewardScrollView.gameObject , isShow)

    SetButtonAction(self.BtnHistory.gameObject , function ()
        UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityFashionPreheatingHistory, parameters = { bigPrizeRecord = self.bigPrizeRecord } })
    end)
    
    SetButtonAction(self.BtnRule, function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityFashionPreheatingRule, parameters = { bigPrizeRecord = self.bigPrizeRecord , ruleId = self.ruleId ,activityContentId = self:GetActivityContentId()  } })
    end)
end

function ActivityFashionPreheating:InitView()
    -- update reward
    self:RefreshReward()
    self:RefreshDrawTimes()
    -- update view
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.activityDt.startTime, self.activityDt.endTime))
    CfUtils.FillText(self.Text, string.trim(self.activityDt.detail) ~= "" and self.activityDt.detail or "TO BE CONTINUE")

    local titleImgUrl = checkString(self.activityDt.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

function ActivityFashionPreheating:RefreshDrawTimes()
    local  num =  GoodsUtils.GetThingNo(self.consumeData[1].goodsId)  
    local oneNum = self.consumeData[1].num 
    CfUtils.FillText(self.TxtNumber ,math.floor(num / oneNum))
    ---@type PlayerDojo
    local playerDojo = PlayerComponent.playerDojo
    local serverTime = playerDojo:GetServerTime()
    local distanceTime = self.prizeCountDown - serverTime
    if math.floor(num / oneNum) > 0 and distanceTime <= 0 then
        ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), 0)
        KTool.SetActive(self.redPoint , true)
    else 
        ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), -1)
        KTool.SetActive(self.redPoint , false)
    end
end

function ActivityFashionPreheating:RefreshGoodNode()
    ---@type UnityEngine.Transform 
    local transform = self.RewardRoot.transform
    local GameObject = CS.UnityEngine.GameObject
    for k, v in pairs(self.myPrize) do
        local go = transform:Find("GoodNode" .. k  )
        if isNull(go) then
            go = GameObject.Instantiate(self.GoodNode ,transform)
            go.name = "GoodNode" .. k 
        end
        local GoodNode = go:Find("GoodNode")
        local Env = CfUtils.GetLuaScr(GoodNode ,  "Game.Behaviours.GoodNodeMB")
        if isNotNull(Env) then
            Env:Reload({
                goodsId = v.goodsId,
                text = string.format("x%d", v.num),
                isShowNo = true
            })
            Env:SetClickButtonAction(function(goodsId, id)
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(GoodNode, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end 
end

function ActivityFashionPreheating:RefreshReward()
    if next(self:GetTaskDt()) == nil then return end

    -- update list
    local totalCount  = #self:GetTaskDt()
    local normalCount = totalCount

    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(normalCount, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListCell, normalCount)
    end
end

----------------------------------------------------------------------------- handler

function ActivityFashionPreheating:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cellNode = listView:NewListViewItem("Cell")
    local nodeEnv  = CfUtils.GetLuaScr(cellNode, "Game.Activity.FashionPreheating.ActivityFashionPreheatingCell")
    if nodeEnv then
        if self:GetItemShowNum() <= 0 then
            local cellSizeH  = cellNode.CachedRectTransform.rect.height + cellNode.Padding
            self.itemShowNum = math.ceil(listView.ViewPortHeight / cellSizeH)
        end
        if not self.animMapList[index + 1] and index <= self:GetItemShowNum() then
            self.animMapList[index + 1] = true
            nodeEnv:PlayFadeInAnim(index)
        else
            nodeEnv:PlayInitAnim()
        end

        nodeEnv:Refresh(self:GetTaskDt()[index + 1], index)
        nodeEnv:SetBtnCB(function(taskId, nodeEnv)
            local status   = nodeEnv:GetStatus()
            local openType = nodeEnv:GetOpenType()
            local openParameter = nodeEnv:GetOpenParameter()
            if status == Constants.GetStatus.Can then
                self:OnDrawTask(taskId, nodeEnv)
            elseif status == Constants.GetStatus.Not then
                if openType > 0 then
                    local goodsConfMgr = GoodsConfMgr:GetInstance()
                    goodsConfMgr:ExecuteJump(goodsConfMgr:GetJumpModuleRow(openType), {}, 0, false, {url = openParameter})
                    KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self:GetActivityId())
                end
            else
                GameUtils.Toast("You have already received the reward")
            end

        end)
    end
    return cellNode
end

function ActivityFashionPreheating:OnDrawTask(taskId, cellEnv)
    taskId = checkInt(taskId)
    GameUtils.Request(Interfaces.Activity2DrawSkinWarmUpTask,
            {activityUuid = self:GetActivityId(), taskId = taskId},
            function(request, response)
                if checkInt(response.errCode) == 0 then

                    -- update data
                    local data = response.data

                    if checkInt(taskId) <= 0 then
                        self.canTaskMap = {}
                    else
                        self.canTaskMap[checkInt(taskId)] = nil
                    end

          
                    for _, taskDt in ipairs(self:GetTaskDt()) do
                        if checkInt(taskDt.id) == taskId then
                            taskDt.status = Constants.GetStatus.Has
                        end
                    end

                    -- refresh reward
                    GoodsUtils.DrawRewards(data.rewards, true)
                    UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards }
                        }
                    )

                    self:RefreshDrawTimes()
                    -- update red
                    if next(self:GetCanIdMap()) == nil then
                        ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), -1)
                    end

                    -- update list
                    if not cellEnv then
                        GameUtils.ReloadData(self.LoopListCell, #self:GetTaskDt())
                    else
                        cellEnv:RefreshStatue()
                    end

                end
            end)
end

function ActivityFashionPreheating:FlashSkinWarmUpPrize()
    GameUtils.Request(Interfaces.Activity2FlashSkinWarmUpPrize,
    {activityUuid = self:GetActivityId()},
    function(request, response)
        if checkInt(response.errCode) == 0 then
            -- update data
            local data = response.data
            local rewards = data.rewards  
            local goodsId = rewards[1].goodsId 
            local consumeData = clone(self.consumeData)
            for k, v in pairs(consumeData) do
                v.num = - v.num 
            end
            for k, v in pairs(rewards) do
                consumeData[#consumeData+1] = v 
            end
            self.myPrize[#self.myPrize+1] = rewards[1]
            GoodsUtils.DrawRewards(consumeData)
            self:RefreshDrawTimes()
            KTool.SetActive(self.RewardScrollView , true)
            self:RefreshGoodNode()
            ---@type GachaponUtils
            local GachaponUtils = import('Game.Gachapon.GachaponUtils')
            local isBig = ActivityFashionPreheatingUtils.IsBigReards(self:GetActivityDt().activityContentId , rewards[1].goodsId)
            local func = function ()
                if isBig then
                    GachaponUtils.OpenDialogAction(Constants.UITypeIds.CommonCardDisplayDialog, {
                        cardInfo   = { { goodsId =  rewards[1].goodsId} },     
                        isSkin = true, 
                        isHideSkip = true,
                        finishCb   = function()
                        end,
                        onCloseCb  = function()
                            UIModule.CloseDialogById(Constants.UITypeIds.CommonCardDisplayDialog)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards , cb = function()
                                ---@type PlayerDojo
                                local playerDojo = PlayerComponent:GetPlayerDojo()
                                local data = {
                                    playerId = playerDojo.playerId , 
                                    playerName = playerDojo.playerName ,
                                    cardSkinId = rewards[1].goodsId,
                                    time = os.time()
                                } 
                                table.insert(self.bigPrizeRecord , 1 , data)
                                -- self.bigPrizeRecord[#self.bigPrizeRecord+1] = data
                                -- self:Refresh(self:GetActivityDt())
                            end} })
                        end,
                        onSkipCb   = function()
            
                        end
                    }, nil)
                else     
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards} })    
                end
                
            end
            UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityFashionPreheatingGetRewards, parameters = { rewardId = rewards[1].goodsId , activityContentId = self:GetActivityContentId(),cb =func } })
        end
    end)
end

return ActivityFashionPreheating